static const float4x4 DITHER_MATRIX = float4x4(
    1.0 / 17.0,  9.0 / 17.0,  3.0 / 17.0, 11.0 / 17.0,
    13.0 / 17.0,  5.0 / 17.0, 15.0 / 17.0,  7.0 / 17.0,
    4.0 / 17.0, 12.0 / 17.0,  2.0 / 17.0, 10.0 / 17.0,
    16.0 / 17.0,  8.0 / 17.0, 14.0 / 17.0,  6.0 / 17.0
);

float minHeight = 0.5;    
float maxHeight = 10.0;   
float minScale  = 0.1; 
float maxScale  = 8.0;  

float heightFactor = saturate((g_camPos.y - minHeight) / (maxHeight - minHeight));
float heightScale  = lerp(minScale, maxScale, heightFactor);

float scaledStartDist = startDistance * heightScale;
float scaledEndDist   = endDistance * heightScale;

float dist = distance(g_camPos, WorldPos);
float alpha = saturate((dist - scaledEndDist) / (scaledStartDist - scaledEndDist));

uint2 pixelPos = uint2(Pos.xy) % 4;
float ditherValue = DITHER_MATRIX[pixelPos.x][pixelPos.y];

clip(alpha - ditherValue);

return Color;

float2 texelSize = float2(1.0/1280.0, 1.0/720.0);

    float3 rgbM  = g_prevPass.Sample(g_sampler, uv).rgb;
    float3 rgbNW = g_prevPass.Sample(g_sampler, uv + float2(-1,-1)*texelSize).rgb;
    float3 rgbNE = g_prevPass.Sample(g_sampler, uv + float2( 1,-1)*texelSize).rgb;
    float3 rgbSW = g_prevPass.Sample(g_sampler, uv + float2(-1, 1)*texelSize).rgb;
    float3 rgbSE = g_prevPass.Sample(g_sampler, uv + float2( 1, 1)*texelSize).rgb;

    float3 luma = float3(0.299, 0.587, 0.114);
    float lumaM  = dot(rgbM,  luma);
    float lumaNW = dot(rgbNW, luma);
    float lumaNE = dot(rgbNE, luma);
    float lumaSW = dot(rgbSW, luma);
    float lumaSE = dot(rgbSE, luma);

    float lumaMin = min(lumaM, min(min(lumaNW, lumaNE), min(lumaSW, lumaSE)));
    float lumaMax = max(lumaM, max(max(lumaNW, lumaNE), max(lumaSW, lumaSE)));

    float2 dir;
    dir.x = -((lumaNW + lumaNE) - (lumaSW + lumaSE));
    dir.y =  ((lumaNW + lumaSW) - (lumaNE + lumaSE));

    float dirReduce = max((lumaNW + lumaNE + lumaSW + lumaSE) * 0.25 * 0.03125, 0.0078125);
    float rcpDirMin = 1.0 / (min(abs(dir.x), abs(dir.y)) + dirReduce);
    dir = clamp(dir * rcpDirMin, -8.0, 8.0) * texelSize;

    float3 rgbA = 0.5 * (
        g_prevPass.Sample(g_sampler, uv + dir * (1.0/3.0 - 0.5)).rgb +
        g_prevPass.Sample(g_sampler, uv + dir * (2.0/3.0 - 0.5)).rgb);
    float3 rgbB = rgbA * 0.5 + 0.25 * (
        g_prevPass.Sample(g_sampler, uv + dir * -0.5).rgb +
        g_prevPass.Sample(g_sampler, uv + dir * 0.5).rgb);

    float lumaB = dot(rgbB, luma);
    if (lumaB < lumaMin || lumaB > lumaMax)
        return float4(rgbA, 1.0);
    return float4(rgbB, 1.0);

static const float3 LumCoeff = float3(0.2126, 0.7152, 0.0722);

float luminance = dot(color.rgb, LumCoeff);
    float3 grayColor = float3(luminance, luminance, luminance);

float3 result = lerp(grayColor, color.rgb, saturation);

    return float4(result, color.a);
